\version "2.27.2"
% automatically converted by musicxml2ly from 41i-PartNameDisplay-Override.xml
\pointAndClickOff

\header {
  texidoc = "MusicXML allows <part-name> and <part-name-display> in the
    <score-part> element. If <part-name-display> is given, it overrides
    <part-name> for display.

    The first staff uses only <part-name>, while the second one (with the same
    <part-name> value) overrides it with a custom text.

    In a similar vein, <part-abbreviation> can be overridden with
    <part-abbreviation-display>, shown in the second system.

    The multi-line entries are generated by using ‘xml:space=\"preserve\"’ as an
    attribute within a <display-text> child of the <xxx-display> element."
}
\layout {
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative c' {
  \once \omit Staff.TimeSignature c1 \break | % 1
  c1 }

PartPTwoVoiceOne = \relative c' {
  \once \omit Staff.TimeSignature c1 \break | % 1
  c1 }


% The score definition
\score {
  <<
    \new Staff = "P1" <<
      \set Staff.instrumentName = "Part name"
      \set Staff.shortInstrumentName = "Abbrev."
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
      >>
    >>
    \new Staff = "P2" <<
      \set Staff.instrumentName = \markup \concat { \center-column { "Part Name"
          Override } }
      \set Staff.shortInstrumentName = \markup \concat { \center-column {
          "Abbrv." "overr." } }
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPTwoVoiceOne" {
          \PartPTwoVoiceOne
        }
      >>
    >>
  >>
  \layout {}
  % To create MIDI output, uncomment the following line:
  % \midi { \tempo 4 = 100 }
}
